/// `cross_norm`'s sign from its `f64` filter, or `None` when the filter's bound cannot certify it.
///
/// `Some(Sign::Zero)` only when the scale is zero, which makes the exact value zero.
#[inline]
#[must_use]
#[allow(
    clippy::similar_names,
    reason = "each name is a step of the description, named by the language's rule"
)]
pub fn filter(a: P3, b: P3, c: P3, d: P3) -> Option<Sign> {
    let p_x = exact_f64(b.x) - exact_f64(a.x);
    let p_y = exact_f64(b.y) - exact_f64(a.y);
    let p_z = exact_f64(b.z) - exact_f64(a.z);
    let q_x = exact_f64(d.x) - exact_f64(c.x);
    let q_y = exact_f64(d.y) - exact_f64(c.y);
    let q_z = exact_f64(d.z) - exact_f64(c.z);
    let n_x_1 = p_y * q_z;
    let n_x_2 = p_z * q_y;
    let n_x = n_x_1 - n_x_2;
    let n_y_1 = p_z * q_x;
    let n_y_2 = p_x * q_z;
    let n_y = n_y_1 - n_y_2;
    let n_z_1 = p_x * q_y;
    let n_z_2 = p_y * q_x;
    let n_z = n_z_1 - n_z_2;
    let nn_1 = n_x * n_x;
    let nn_2 = n_y * n_y;
    let nn_3 = nn_1 + nn_2;
    let nn_4 = n_z * n_z;
    let nn = nn_3 + nn_4;
    let m_x = largest_magnitude([p_x, q_x]);
    let m_y = largest_magnitude([p_y, q_y]);
    let m_z = largest_magnitude([p_z, q_z]);
    let scale = larger(m_y * m_y * m_z * m_z, m_x * m_x * m_z * m_z);
    let scale = larger(scale, m_x * m_x * m_y * m_y);
    decide(nn, ERROR, scale)
}

/// `cross_norm`'s exact value: each step in the type its certificate gives it, with checked
