    let n_x_2 = i128::from(p_z).checked_mul(i128::from(q_y))?;
    let n_x = n_x_1.checked_sub(n_x_2)?;
    let n_y_1 = i128::from(p_z).checked_mul(i128::from(q_x))?;
    let n_y_2 = i128::from(p_x).checked_mul(i128::from(q_z))?;
    let n_y = n_y_1.checked_sub(n_y_2)?;
    let n_z_1 = i128::from(p_x).checked_mul(i128::from(q_y))?;
    let n_z_2 = i128::from(p_y).checked_mul(i128::from(q_x))?;
